import { i as buildConfig } from "./core-BHawVsTm.js";
import fs from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";
//#region src/config/load-from-file.ts
async function compileConfig(core) {
	const { build } = await import("esbuild");
	let source;
	try {
		source = await fs.readFile(core.configPath, "utf-8");
	} catch (error) {
		if (error.code === "ENOENT") return false;
		throw error;
	}
	if ((await build({
		stdin: {
			contents: source,
			sourcefile: path.basename(core.configPath),
			resolveDir: path.dirname(core.configPath),
			loader: core.configPath.endsWith(".js") || core.configPath.endsWith(".mjs") ? "js" : "ts"
		},
		bundle: true,
		outfile: path.join(core.outDir, "source.config.mjs"),
		target: "node22",
		write: true,
		platform: "node",
		format: "esm",
		packages: "external",
		allowOverwrite: true
	})).errors.length > 0) throw new Error("failed to compile configuration file");
	return true;
}
/**
* Load config
*
* @param build - By default, it assumes the config file has been compiled. Set this `true` to compile the config first.
*/
async function loadConfig(core, build = false) {
	let exists;
	if (build) exists = await compileConfig(core);
	exists ??= await fs.access(core.configPath).then(() => true, () => false);
	if (!exists) return {
		config: buildConfig({}, process.cwd()),
		fromFile: false
	};
	const url = pathToFileURL(core.getCompiledConfigPath());
	url.searchParams.set("hash", Date.now().toString());
	return {
		config: buildConfig(await import(url.href), process.cwd()),
		fromFile: true
	};
}
